namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
            new() { Id = 4, Name = "English", Abbreviation = "ENG" },
            new() { Id = 5, Name = "History", Abbreviation = "HIST" }
        };

        _courses = new List<Course>
        {
            new()
            {
                Id = 1, CourseCode = "CS101", Title = "Introduction to Programming",
                Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control structures, functions, and basic data structures.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM",
                InstructorName = "Dr. Sarah Chen",
                InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has 15 years of teaching experience. Her research focuses on programming education and software engineering.",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true
            },
            new()
            {
                Id = 2, CourseCode = "CS201", Title = "Data Structures and Algorithms",
                Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms).",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM",
                InstructorName = "Dr. James Park",
                InstructorBio = "Dr. Park is an expert in algorithm design and competitive programming. He has published over 40 papers in top-tier venues and mentors the university ACM team.",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true
            },
            new()
            {
                Id = 3, CourseCode = "CS301", Title = "Database Systems",
                Description = "Introduction to database design, relational algebra, SQL, transaction management, and modern NoSQL systems.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM",
                InstructorName = "Dr. Maria Lopez",
                InstructorBio = "Dr. Lopez has extensive industry experience at major tech companies and brings practical database administration expertise to her teaching.",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false
            },
            new()
            {
                Id = 4, CourseCode = "MATH101", Title = "Calculus I",
                Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM",
                InstructorName = "Dr. Robert Taylor",
                InstructorBio = "Dr. Taylor is an award-winning mathematics educator who has authored two popular calculus textbooks used at universities worldwide.",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true
            },
            new()
            {
                Id = 5, CourseCode = "MATH201", Title = "Linear Algebra",
                Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to computer graphics and machine learning.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM",
                InstructorName = "Dr. Emily White",
                InstructorBio = "Dr. White specializes in applied mathematics and has collaborated with NASA on trajectory computation projects.",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false
            },
            new()
            {
                Id = 6, CourseCode = "MATH301", Title = "Probability and Statistics",
                Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis with real-world applications.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM",
                InstructorName = "Dr. Robert Taylor",
                InstructorBio = "Dr. Taylor is an award-winning mathematics educator who has authored two popular calculus textbooks used at universities worldwide.",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false
            },
            new()
            {
                Id = 7, CourseCode = "PHYS101", Title = "General Physics I",
                Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.",
                Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM + Lab Fri 2:00–4:50 PM",
                InstructorName = "Dr. Alan Foster",
                InstructorBio = "Dr. Foster is a former CERN researcher who brings particle physics experience to undergraduate teaching. He is passionate about making physics accessible.",
                DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true
            },
            new()
            {
                Id = 8, CourseCode = "PHYS201", Title = "Electromagnetism",
                Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves. Mathematical prerequisites include multivariable calculus.",
                Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Tue 3:00–5:50 PM",
                InstructorName = "Dr. Nina Patel",
                InstructorBio = "Dr. Patel's research in superconducting materials has earned her national recognition. She enjoys connecting cutting-edge research to course material.",
                DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false
            },
            new()
            {
                Id = 9, CourseCode = "ENG101", Title = "English Composition",
                Description = "Develop clear, effective academic writing skills. Focus on thesis development, argumentation, research methods, and proper citation.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM",
                InstructorName = "Prof. David Kim",
                InstructorBio = "Prof. Kim is a published author and writing coach with a Master of Fine Arts from the Iowa Writers' Workshop.",
                DepartmentId = 4, DepartmentName = "English", IsFeatured = false
            },
            new()
            {
                Id = 10, CourseCode = "ENG201", Title = "American Literature",
                Description = "Survey of major American literary works from the colonial period to the present, including novels, poetry, and essays.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM",
                InstructorName = "Dr. Rachel Green",
                InstructorBio = "Dr. Green is a specialist in 20th-century American fiction and has published extensively on the works of Toni Morrison and Cormac McCarthy.",
                DepartmentId = 4, DepartmentName = "English", IsFeatured = false
            },
            new()
            {
                Id = 11, CourseCode = "HIST101", Title = "World History to 1500",
                Description = "Survey of major civilizations, cultural exchanges, and transformative events from antiquity through the late medieval period.",
                Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM",
                InstructorName = "Dr. Michael Brown",
                InstructorBio = "Dr. Brown is an archaeologist and historian who has led excavations in the Mediterranean. He integrates primary sources and material culture into his teaching.",
                DepartmentId = 5, DepartmentName = "History", IsFeatured = false
            },
            new()
            {
                Id = 12, CourseCode = "HIST201", Title = "Modern European History",
                Description = "Political, social, and cultural developments in Europe from the Enlightenment through the 21st century, including revolutions, world wars, and the EU.",
                Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM",
                InstructorName = "Dr. Lisa Wang",
                InstructorBio = "Dr. Wang specializes in modern European diplomatic history and has served as a visiting scholar at Oxford and the Sorbonne.",
                DepartmentId = 5, DepartmentName = "History", IsFeatured = true
            }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);
}

