@page "/"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="container">
    <div class="hero">
        <h1>University Course Catalog</h1>
        <p class="lead">Explore our departments and courses for the upcoming semester.</p>
        <a href="/courses" class="btn btn-primary btn-lg">Browse All Courses</a>
    </div>

    <section class="mt-5">
        <h2>Featured Courses</h2>
        <div class="row mt-3">
            @foreach (var course in _featuredCourses)
            {
                <div class="col-md-6 col-lg-4 mb-4">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@course.CourseCode — @course.Title</h5>
                            <p class="card-text text-muted">@course.DepartmentName · @course.Credits credits</p>
                            <p class="card-text">@Truncate(course.Description, 120)</p>
                        </div>
                        <div class="card-footer bg-transparent">
                            <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>

    <section class="mt-5">
