                <p>@_course.Description</p>

                <h4 class="mt-4">Schedule</h4>
                <p><span class="badge bg-secondary me-2">@_course.Credits credits</span> @_course.Schedule</p>
            </div>

            <div class="col-lg-4">
                <div class="card mt-4 mt-lg-0">
                    <div class="card-header">
                        <h5 class="mb-0">Instructor</h5>
                    </div>
                    <div class="card-body">
                        <h6>@_course.InstructorName</h6>
                        <p class="card-text">@_course.InstructorBio</p>
