@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="container">
    <div class="hero">
        <h1>University Course Catalog</h1>
        <p class="lead">Explore our departments and courses for the upcoming semester.</p>
        <a href="/courses" class="btn btn-primary btn-lg">Browse All Courses</a>
    </div>

    <section class="mt-5">
        <h2>Featured Courses</h2>
        <div class="row mt-3">
            @foreach (var course in _featuredCourses)
            {
                <div class="col-md-6 col-lg-4 mb-4">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@course.CourseCode — @course.Title</h5>
                            <p class="card-text text-muted">@course.DepartmentName · @course.Credits credits</p>
                            <p class="card-text">@Truncate(course.Description, 120)</p>
                        </div>
                        <div class="card-footer bg-transparent">
                            <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>

    <section class="mt-5">
        <h2>Departments</h2>
        <div class="row mt-3">
            @foreach (var dept in _departments)
            {
                <div class="col-md-4 col-lg-3 mb-3">
                    <a href="/courses?departmentId=@dept.Id" class="text-decoration-none">
                        <div class="card text-center p-3 h-100 department-card">
                            <div class="card-body">
                                <h5 class="card-title mb-1">@dept.Name</h5>
                                <p class="card-text text-muted">@dept.Abbreviation</p>
                            </div>
                        </div>
                    </a>
                </div>
            }
        </div>
    </section>
</div>

@code {
    private List<Course> _featuredCourses = new();
    private List<Department> _departments = new();

    protected override void OnInitialized()
    {
        _featuredCourses = CatalogService.GetFeaturedCourses();
        _departments = CatalogService.GetDepartments();
    }

    private static string Truncate(string text, int maxLength)
    {
        if (text.Length <= maxLength) return text;
        return text[..maxLength].TrimEnd() + "…";
    }
